/// <summary>
/// MPJ_5013_ExciseRegisterEntry
/// </summary>
[DataContractAttribute,
SysOperationContractProcessingAttribute(classStr(METUpdateExciseRegisterUIBuilder))]
public class METUpdateExciseRegisterContract 
{
    SalesId             salesId;
    InventTransferId    transferId;
    InventJournalId     inventJournalId;

}

Method.Source:
  /// <summary>
  /// Parameters to include SalesId
  /// </summary>
  /// <param name = "_salesId">salesid</param>
  /// <returns>sales id</returns>
  [
  DataMemberAttribute,
  SysOperationLabelAttribute(literalStr("@SYS9694")),
  SysOperationHelpTextAttribute(literalStr("@SYS9694")),
  SysOperationDisplayOrderAttribute('1')
  ]

  public SalesId parmSalesId(SalesIdBase _salesId = salesId)
  {
      salesId = _salesId;
      return salesId;
  }

  /// <summary>
