  /// </summary>
  /// <param name = "_inventJournalId">journal Id</param>
  /// <returns>journal id</returns>
  [
  DataMemberAttribute,
  SysOperationLabelAttribute(literalStr("@SYS6790")),
  SysOperationDisplayOrderAttribute('3')
  ]

  public InventJournalId parmInventJournalId(InventJournalId _inventJournalId = inventJournalId)
